/* teach_data.js - Teaching template: History taking (hx) and Physical examination (pe)
   Sources: Bates' Guide to Physical Examination and History Taking 13e, Macleod's Clinical Examination, Thai clinical practice.
   tag: "" = general, "ped" = pediatric only, "ob" = obstetric/gynecologic only. */
const TCH_DEF={
 hx:[
  {id:"pid", h:"Patient identification / profile (ข้อมูลทั่วไป)", tag:"", c:"<ul><li><b>ชื่อ-สกุล, HN/AN</b>, อายุ (เด็ก: วัน/เดือน/ปี), เพศ, วัน-เวลาที่รับไว้หรือตรวจ</li><li>เชื้อชาติ สัญชาติ ศาสนา (มีผลต่อการรักษา เช่น การรับเลือด/อาหาร), สถานภาพสมรส, การศึกษา, อาชีพ</li><li>ภูมิลำเนา / ที่อยู่ปัจจุบัน (ระบุจังหวัด เพื่อดู endemic area), ถนัดมือซ้ายหรือขวา (สำคัญใน neuro), ภาษาที่ใช้ (ล่ามถ้าจำเป็น)</li><li><b>ผู้ให้ประวัติ (informant)</b>: ผู้ป่วยเอง / ญาติ / ผู้พาส่ง / referral letter และ <b>ความน่าเชื่อถือ (reliability)</b>; ในเด็กระบุความสัมพันธ์ของผู้ให้ประวัติ (เช่น มารดา)</li><li>มาโรงพยาบาลด้วยวิธีใด (walk-in, EMS 1669, refer จาก รพ.ใด, นัดตรวจ)</li><li>ก่อนเริ่ม: แนะนำตัว ล้างมือ ขออนุญาต ถามชื่อที่อยากให้เรียก จัดที่ให้เป็นส่วนตัว</li></ul>"},
  {id:"cc", h:"Chief complaint (CC)", tag:"", c:"<ul><li>อาการสำคัญที่ทำให้มา รพ. <b>ใช้คำของผู้ป่วยเอง</b> 1-2 อาการ (ไม่ใช่ diagnosis) + <b>ระยะเวลา</b></li><li>รูปแบบการเขียน: <b>'อาการ + ระยะเวลา + PTA'</b> เช่น 'ไข้ ไอ 3 วัน PTA', 'จุกแน่นหน้าอก 2 ชม. PTA'</li><li>ถ้ามีหลายอาการ เรียงตามลำดับความสำคัญหรือเวลาที่เกิด; ถ้ามาตรวจตามนัด/ตรวจสุขภาพ ให้ระบุเหตุผล (follow-up, check-up, refer)</li><li>คำถามเปิด: 'วันนี้มีอะไรให้ช่วยคะ/ครับ', 'อะไรที่ทำให้ต้องมาโรงพยาบาลวันนี้', 'อาการอะไรที่รบกวนมากที่สุด'</li><li>PTA = prior to admission / ก่อนมา รพ.</li></ul>"},
  {id:"hpi", h:"Present illness (HPI)", tag:"", c:"<b>เล่าเป็นลำดับเวลา (chronological)</b> เริ่มจากตอนที่ยังปกติ ถามคำถามปลายเปิดก่อน แล้วค่อยปิด<ul><li><b>OLD CARTS</b>: <b>O</b>nset (เริ่มเมื่อไร ทันทีหรือค่อยเป็น ขณะทำอะไร), <b>L</b>ocation, <b>D</b>uration, <b>C</b>haracter (ลักษณะ), <b>A</b>ggravating / <b>A</b>lleviating factors, <b>R</b>adiation, <b>T</b>iming (ตลอดเวลา / เป็นๆหายๆ / ช่วงเวลาของวัน), <b>S</b>everity (pain score 0-10, กระทบชีวิตประจำวันแค่ไหน)</li><li>อาการเจ็บ ใช้ <b>SOCRATES</b>: Site, Onset, Character, Radiation, Associations, Time course, Exacerbating/relieving, Severity</li><li><b>Associated symptoms</b> และ <b>pertinent positive / negative</b> (อาการที่ช่วยแยก DDx; ถามเชิงระบบของอวัยวะที่เกี่ยวข้อง)</li><li>เคยมีอาการแบบนี้มาก่อนไหม, ปัจจัยเสี่ยง/สิ่งกระตุ้น, ผู้ใกล้ชิดป่วยคล้ายกัน, สัมผัสโรค</li><li><b>การรักษาที่ได้รับ</b>: ซื้อยากินเอง, คลินิก/รพ.อื่น (ยาอะไร ขนาดเท่าไร ตอบสนองอย่างไร)</li><li><b>Course</b>: อาการแย่ลง คงที่ หรือดีขึ้น, เหตุผลที่ตัดสินใจมา รพ. วันนี้</li><li>ผลกระทบต่อการใช้ชีวิต, ความกังวลและความคาดหวังของผู้ป่วย (ICE: Ideas, Concerns, Expectations)</li></ul>"},
  {id:"pmh", h:"Past history (ประวัติในอดีต)", tag:"", c:"<ul><li><b>โรคประจำตัว</b>: DM, HT, DLP, heart disease, CKD, asthma/COPD, TB, thyroid, cancer, HIV, hepatitis B/C, epilepsy, stroke, psychiatric - ระบุปีที่วินิจฉัย การควบคุม ยาที่ใช้ ภาวะแทรกซ้อน สถานที่รักษา/นัดล่าสุด; ภาวะเลือดจาง thalassemia, G6PD deficiency (พบบ่อยในไทย)</li><li><b>เคยนอน รพ. / ผ่าตัด</b>: ปี สถานที่ สาเหตุ การดมยา/ภาวะแทรกซ้อน</li><li><b>ยาที่ใช้ประจำ</b>: ชื่อ ขนาด ความถี่ ความสม่ำเสมอ รวม OTC, ยาชุด, ยาลูกกลอน, <b>สมุนไพร/อาหารเสริม/ยาหม้อ</b> (อาจปนสเตียรอยด์), ยาคุมกำเนิด, วิตามิน</li><li><b>การแพ้</b>: ยา (ชื่อยา), อาหาร (เช่น อาหารทะเล), สารอื่น (latex) + <b>ลักษณะปฏิกิริยา</b> (ผื่น, angioedema, anaphylaxis, SJS/TEN), เวลาที่เกิด, มีบัตรแพ้ยาหรือไม่</li><li><b>ประวัติได้รับเลือด</b> และปฏิกิริยา</li><li><b>อุบัติเหตุ / กระดูกหัก / บาดเจ็บ</b></li><li>วัคซีนในผู้ใหญ่ (tetanus, HBV, influenza, COVID-19), การตรวจคัดกรองที่ผ่านมา</li></ul>"},
  {id:"soc", h:"Personal and social history", tag:"", c:"<ul><li><b>สูบบุหรี่</b>: ชนิด (บุหรี่ซอง, ยาเส้น/ใบจาก, บุหรี่ไฟฟ้า), อายุที่เริ่ม, ปริมาณ, เลิกเมื่อไร; <b>pack-years = (จำนวนซอง/วัน) x (จำนวนปีที่สูบ)</b> (1 ซอง = 20 มวน)</li><li><b>แอลกอฮอล์</b>: ชนิด ปริมาณ (standard drinks) ความถี่ ระยะเวลา, binge drinking; คัดกรองด้วย CAGE / AUDIT</li><li><b>สารเสพติด</b>: ยาบ้า/ไอซ์ กัญชา กระท่อม ยาฉีดเข้าเส้น (IVDU - เสี่ยง HIV/HCV/HBV), การใช้ยานอนหลับ</li><li><b>อาชีพ / สิ่งแวดล้อม</b>: สารเคมี ยาฆ่าแมลงในเกษตรกร ฝุ่นซิลิกา ใยหิน เสียงดัง เข็มตำ (บุคลากรการแพทย์); งานอดิเรก</li><li><b>การเดินทาง / ความเสี่ยงโรคติดเชื้อ</b>: พื้นที่ป่า-ชายแดน (malaria), น้ำท่วมขัง/ย่ำน้ำนา (leptospirosis, melioidosis), สัมผัสสัตว์ (สุนัข-แมวกัด: rabies, หมู: S. suis, นก), กินปลาน้ำจืดดิบ ก้อยปลา ปลาร้า (liver fluke), หมูดิบ, น้ำ-อาหารไม่สะอาด, ผู้ป่วย TB ใกล้ชิด, เดินทางต่างประเทศ</li><li><b>ประวัติทางเพศ</b> (5 Ps): Partners, Practices, Protection (ถุงยาง), Past STI, Prevention of pregnancy; ตรวจ HIV ล่าสุด - ถามอย่างให้เกียรติ ไม่ตัดสิน</li><li><b>อาหาร / การออกกำลังกาย / การนอน</b>, ความเครียด ภาวะซึมเศร้า</li><li><b>ที่อยู่อาศัย</b>: อยู่กับใคร ผู้ดูแลหลัก สุขาภิบาล น้ำดื่ม ผู้สูงอายุอยู่คนเดียวหรือไม่; ADL</li><li><b>สิทธิการรักษา</b>: บัตรทอง (UCS) / ประกันสังคม / ข้าราชการ (CSMBS) / ประกันเอกชน / ชำระเอง; สถานพยาบาลต้นสังกัด (มีผลต่อการ refer)</li></ul>"},
  {id:"fhx", h:"Family history", tag:"", c:"<ul><li>ถามพ่อ แม่ พี่น้อง ลูก (อย่างน้อย 3 generations) - อายุ ยังมีชีวิตอยู่หรือไม่ สาเหตุการเสียชีวิต/อายุที่เสีย</li><li><b>โรคทางพันธุกรรม / ครอบครัว</b>: DM, HT, CAD / early MI (ชาย &lt;55 ปี, หญิง &lt;65 ปี), stroke, DLP, มะเร็ง (เต้านม รังไข่ ลำไส้ใหญ่ ต่อมลูกหมาก), thalassemia, G6PD, hemophilia, polycystic kidney, asthma/atopy, epilepsy, psychiatric, dementia</li><li><b>โรคติดเชื้อในบ้าน</b>: TB, ไข้หวัดใหญ่/COVID-19, hepatitis B (แม่เป็นพาหะ), ไข้เลือดออก, คนในบ้านมีอาการคล้ายกัน</li><li>เครือญาติแต่งงานกัน (consanguinity)</li><li>เขียน <b>pedigree / genogram</b>: สี่เหลี่ยม = ชาย, วงกลม = หญิง, ทึบ = ป่วย, ขีดฆ่า = เสียชีวิต</li></ul>"},
  {id:"ros", h:"Review of systems (ROS)", tag:"", c:"ถามอาการเชิงระบบ <b>นอกเหนือจาก HPI</b> (ถามอาการที่ยังไม่ได้ครอบคลุม สั้นๆ ตอบ มี/ไม่มี)<ul><li><b>General</b>: ไข้ ครั่นเนื้อครั่นตัว เหงื่อออกกลางคืน อ่อนเพลีย น้ำหนักเปลี่ยน (กี่ kg ใน กี่เดือน) เบื่ออาหาร</li><li><b>Skin</b>: ผื่น คัน ฝี ไฝเปลี่ยน, ผมร่วง; <b>HEENT</b>: ปวดศีรษะ ตามัว/เห็นภาพซ้อน ตาแดง หูอื้อ ได้ยินลดลง คัดจมูก เลือดกำเดา เจ็บคอ กลืนลำบาก เสียงแหบ ก้อนที่คอ</li><li><b>Respiratory</b>: ไอ เสมหะ ไอเป็นเลือด หอบเหนื่อย หายใจมีเสียงวี้ด เจ็บหน้าอกเวลาหายใจ</li><li><b>Cardiovascular</b>: เจ็บแน่นหน้าอก ใจสั่น orthopnea PND บวมเท้า เป็นลม (syncope) ปวดน่องเวลาเดิน (claudication)</li><li><b>GI</b>: คลื่นไส้ อาเจียน (hematemesis) ปวดท้อง กลืนเจ็บ ท้องอืด ถ่ายเหลว/ท้องผูก ถ่ายดำ/ถ่ายเป็นเลือด ตาเหลือง ตัวเหลือง</li><li><b>GU</b>: ปัสสาวะแสบขัด บ่อย กลางคืนบ่อย (nocturia) เป็นเลือด ปัสสาวะไม่พุ่ง/สะดุด ปวดเอว กลั้นไม่ได้; ตกขาว แผล/ผื่นที่อวัยวะเพศ</li><li><b>Endocrine</b>: ทนร้อน/หนาวไม่ได้ ใจสั่น มือสั่น กินจุ ดื่มน้ำมาก ปัสสาวะมาก</li><li><b>Hematologic</b>: ซีด จ้ำเลือด เลือดออกง่าย ต่อมน้ำเหลืองโต; <b>MSK</b>: ปวด บวม ข้อฝืดตอนเช้า (นาที), ปวดหลัง กล้ามเนื้ออ่อนแรง</li><li><b>Neuro</b>: ชา อ่อนแรง เวียนศีรษะ (vertigo) ชัก พูดไม่ชัด เดินเซ ความจำ; <b>Psychiatric</b>: อารมณ์ซึมเศร้า วิตกกังวล นอนไม่หลับ ความคิดทำร้ายตนเอง</li></ul>"},
  {id:"birth", h:"Birth history (ประวัติการตั้งครรภ์และการคลอด)", tag:"ped", c:"<ul><li><b>Prenatal</b>: อายุมารดา, G_P_A_L, ฝากครรภ์เมื่อไร กี่ครั้ง, โรคของแม่ (HT/preeclampsia, GDM, thyroid, SLE), ติดเชื้อขณะตั้งครรภ์ (TORCH, ซิฟิลิส, HIV, HBsAg), ผลเลือด thalassemia screening, ยา/แอลกอฮอล์/บุหรี่/สารเสพติด, รังสี, ภาวะแท้งคุกคาม, U/S ผิดปกติ, เด็กดิ้นดี, วัคซีนแม่ (dT, influenza)</li><li><b>Natal</b>: อายุครรภ์ (term 37-41+6 สัปดาห์; preterm &lt;37), วิธีคลอด (NL / C-section / vacuum / forceps) และข้อบ่งชี้, สถานที่คลอด, น้ำคร่ำแตกก่อนคลอดนานเท่าไร, meconium-stained, ท่าเด็ก, ระยะเวลาเจ็บครรภ์, ภาวะ fetal distress</li><li><b>เกิด</b>: น้ำหนักแรกเกิด (ปกติ 2,500-4,000 g; LBW &lt;2,500, VLBW &lt;1,500), ความยาว, รอบศีรษะ, <b>APGAR</b> 1 และ 5 นาที, ร้องทันทีหรือไม่, ต้อง resuscitate หรือไม่, AGA / SGA / LGA</li><li><b>Postnatal / neonatal</b>: ตัวเหลือง (ส่องไฟ/เปลี่ยนถ่ายเลือด), หายใจลำบาก/RDS/ใส่ท่อ, NICU กี่วัน, ชัก, ติดเชื้อ, hypoglycemia, ดูดนมได้ดีหรือไม่, ได้ vitamin K, BCG, HBV, <b>newborn screening</b> (TSH, PKU, G6PD ฯลฯ), ตรวจการได้ยิน, กลับบ้านวันที่เท่าไร</li></ul>"},
  {id:"gd", h:"Growth and development (การเจริญเติบโตและพัฒนาการ)", tag:"ped", c:"<ul><li><b>Growth</b>: น้ำหนัก ส่วนสูง/ความยาว รอบศีรษะ เทียบกับ <b>growth chart</b> (สมุดบันทึกสุขภาพแม่และเด็ก) - เส้นโค้งอยู่ใน percentile/SD เดิมหรือไม่, น้ำหนักหยุดขึ้น/ลดลงหรือไม่</li><li><b>พัฒนาการ 5 ด้าน (DSPM)</b>: GM (gross motor), FM (fine motor-adaptive), RL (receptive language), EL (expressive language), PS (personal-social)</li><li><b>Milestones โดยประมาณ</b>: ยิ้มตอบ 2 เดือน; ชันคอ 3-4 เดือน; พลิกคว่ำ-หงาย 4-6 เดือน; นั่งเองได้ 6-7 เดือน; คลาน 8-9 เดือน; ยืนเกาะ 9 เดือน; เดินเองได้ 12-15 เดือน; วิ่ง 18-24 เดือน; ขึ้นบันได 2 ปี; ปั่นสามล้อ 3 ปี; กระโดดขาเดียว 4 ปี<br>จับของ 4-5 เดือน; ย้ายของมือ 6 เดือน; หยิบด้วยนิ้วชี้-หัวแม่มือ (pincer) 9-10 เดือน; ขีดเขียน 15 เดือน; วาดวงกลม 3 ปี, กากบาท 4 ปี, สามเหลี่ยม 5 ปี<br>ส่งเสียง cooing 2 เดือน; babbling 6 เดือน; เรียกพ่อแม่ถูกคน/คำแรก ~12 เดือน; 2 คำต่อกัน 2 ปี; ประโยค 3 ปี</li><li>สัญญาณเตือน: ถดถอยของทักษะ (regression), พัฒนาการช้าด้านใดด้านหนึ่งหรือหลายด้าน, ไม่สบตา/ไม่เรียกชื่อหัน</li><li>การเรียน/โรงเรียน พฤติกรรม การนอน ปัญหาด้านสังคม; เครื่องมือประเมิน: DSPM, Denver II, ASQ</li></ul>"},
  {id:"imm", h:"Immunization history (ประวัติวัคซีน)", tag:"ped", c:"ตรวจจาก <b>สมุดบันทึกสุขภาพแม่และเด็ก (สมุดสีชมพู)</b> ทุกครั้ง - ตารางมีการปรับตามปี ให้ตรวจเทียบตารางล่าสุดของกรมควบคุมโรค<ul><li><b>แรกเกิด</b>: BCG, HBV</li><li><b>2, 4, 6 เดือน</b>: DTP-HB-Hib และโปลิโอ (OPV; IPV ตามโปรแกรม)</li><li><b>9-12 เดือน</b>: MMR (เข็มที่ 1)</li><li><b>1 ปี / 2.5 ปี</b>: JE (Japanese encephalitis); <b>2.5 ปี</b>: MMR เข็มที่ 2</li><li><b>1.5 ปี และ 4-6 ปี</b>: กระตุ้น DTP + OPV</li><li><b>วัยเรียน</b>: ป.1 / ป.6 dT; <b>HPV</b> ในเด็กหญิง ป.5 (2 เข็ม)</li><li>วัคซีนเสริม/นอกโครงการ (ขึ้นกับช่วงเวลา-พื้นที่): influenza, rotavirus, PCV, Hep A, varicella, EV71, dengue ฯลฯ</li><li>ถาม: ได้ครบตามนัดหรือไม่, เข็มที่ขาด, ปฏิกิริยาหลังฉีด (ไข้สูง ชัก แพ้รุนแรง), ปฏิกิริยาต่อ BCG (แผลเป็น)</li></ul>"},
  {id:"feed", h:"Feeding and nutrition history", tag:"ped", c:"<ul><li><b>ทารก</b>: นมแม่ (exclusive breastfeeding 6 เดือน), ความถี่/ระยะเวลาต่อมื้อ, นมผสม (ยี่ห้อ/ชนิด, วิธีชงตามสัดส่วน, ปริมาตร ต่อมื้อ x จำนวนมื้อ), ท่าให้นม, ปัญหาการดูด/สำลัก/แหวะนม</li><li><b>อาหารตามวัย (complementary food)</b>: เริ่มเมื่อไร (ประมาณ 6 เดือน), ชนิด (ข้าว ไข่แดง ตับ ผัก เนื้อสัตว์ ผลไม้), ความหยาบของอาหาร, เมื่ออายุ 1 ปีกินอาหาร 3 มื้อ + นม 2-3 มื้อ; ธาตุเหล็กเสริม, วิตามิน D</li><li><b>เด็กโต</b>: 24-hour dietary recall, เลือกกิน, ขนม น้ำหวาน น้ำอัดลม ไขมัน ผักผลไม้, ความอยากอาหาร, ปริมาณนมวัว, การกินอาหารระหว่างมื้อ</li><li><b>ประวัติแพ้อาหาร</b> (นมวัว ไข่ ถั่ว อาหารทะเล) และอาการ; อาการท้องเสีย ท้องผูก ถ่ายอุจจาระ</li><li>ผู้เลี้ยงดูหลัก, รูปแบบการให้อาหาร (ป้อน หรือให้กินเอง), สุขอนามัยขวดนม/น้ำที่ใช้ชง</li><li>ประเมินเทียบกับน้ำหนักเด็ก: ได้รับพลังงานพอหรือไม่, เสี่ยง undernutrition / ภาวะอ้วน</li></ul>"},
  {id:"obhx", h:"Obstetric history (ประวัติทางสูติกรรม)", tag:"ob", c:"<ul><li><b>G_P_A_L</b> (Gravida, Para, Abortion, Living) หรือ TPAL เช่น G2P1001 - นับครรภ์ปัจจุบันใน G</li><li><b>LMP</b> (จำได้แน่นอน? ปกติ? ปริมาณปกติ?), PMP, <b>EDC (Naegele's rule)</b> = LMP + 7 วัน - 3 เดือน (หรือ +9 เดือน); อายุครรภ์ (GA) เทียบกับ U/S ไตรมาสแรก (CRL)</li><li><b>ANC</b>: ฝากครรภ์เมื่อไร กี่ครั้ง ที่ใด; ผลตรวจ (Hb/Hct, blood group + Rh, VDRL, HIV, HBsAg, thalassemia screening, OGTT/GCT 24-28 สัปดาห์), U/S, วัคซีน dT / Tdap / influenza, ยาเสริมธาตุเหล็ก-folic acid</li><li><b>ครรภ์ก่อนๆ</b>: ปี, อายุครรภ์ตอนคลอด, วิธีคลอด (NL / C-section / vacuum), BW ทารก, เพศ, ภาวะแทรกซ้อน (preeclampsia, GDM, PPH, preterm, คลอดติดไหล่), ทารกสุขภาพดีหรือไม่, ให้นมแม่; ประวัติแท้ง/ท้องนอกมดลูก/ทำแท้ง</li><li><b>อาการครรภ์ปัจจุบัน</b>: เลือดออกทางช่องคลอด, น้ำเดิน, เจ็บครรภ์ / มดลูกหดรัดตัว, เด็กดิ้น (เริ่มรู้สึก ~16-20 สัปดาห์), ปวดศีรษะ ตามัว จุกลิ้นปี่ บวม (preeclampsia), คลื่นไส้อาเจียนมาก, ไข้ ตกขาว ปัสสาวะแสบ</li><li>ผ่าตัดทางนรีเวช/มดลูก (C-section, myomectomy), โรคประจำตัวขณะตั้งครรภ์</li></ul>"},
  {id:"mens", h:"Menstrual and gynecologic history", tag:"ob", c:"<ul><li><b>Menarche</b> (อายุ), <b>รอบเดือน</b>: ระยะห่างจากวันแรกของรอบหนึ่งถึงวันแรกของรอบถัดไป (ปกติ ~21-35 วัน), ระยะเวลามา (ปกติ 2-7 วัน), ความสม่ำเสมอ, ปริมาณ (จำนวนผ้าอนามัย/วัน, ก้อนเลือด, ซึมเปื้อน)</li><li><b>LMP, PMP</b>, ปวดประจำเดือน (dysmenorrhea) - รบกวนชีวิตไหม, PMS</li><li><b>เลือดออกผิดปกติ</b>: intermenstrual, postcoital, postmenopausal bleeding (AUB, แยกสาเหตุ PALM-COEIN)</li><li><b>วัยหมดประจำเดือน</b>: อายุ, อาการ (ร้อนวูบวาบ), HRT</li><li><b>ตกขาว</b>: สี กลิ่น คัน; ปวดท้องน้อย; dyspareunia; ปัสสาวะผิดปกติ/กลั้นไม่ได้; มดลูกหย่อน</li><li>ประวัติ STI / PID; <b>Pap smear / HPV test</b> ครั้งล่าสุด และผล (โครงการคัดกรองไทย: ~อายุ 30-60 ปี ทุก 5 ปี), วัคซีน HPV; mammography / คลำเต้านม</li><li>ประวัติผ่าตัดนรีเวช (ตัดมดลูก รังไข่ เนื้องอก), ภาวะมีบุตรยาก (ระยะเวลาที่พยายาม)</li></ul>"},
  {id:"contra", h:"Contraception history", tag:"ob", c:"<ul><li>ปัจจุบันและในอดีตใช้วิธีใด: <b>ยาเม็ดคุมกำเนิด (COC / progestin-only), ยาฉีด DMPA (ทุก 3 เดือน), ยาฝังคุม (implant, 3 ปี), ห่วงอนามัย (copper IUD / LNG-IUS), ถุงยางอนามัยชาย-หญิง, การทำหมัน (ท่อนำไข่ / vasectomy), ยาคุมฉุกเฉิน, นับวัน / หลั่งภายนอก</b></li><li>ใช้นานเท่าไร, ลืมยา/ใช้ถูกวิธีหรือไม่, ผลข้างเคียง (เลือดออกกะปริบกะปรอย, ประจำเดือนขาด, น้ำหนักขึ้น, ปวดศีรษะ), ความพึงพอใจ, เหตุผลที่หยุด</li><li><b>ข้อห้าม / ความเสี่ยง</b> (ดู WHO MEC): สูบบุหรี่ อายุ &gt;35, ไมเกรนที่มี aura, VTE / thrombophilia, HT ที่ควบคุมไม่ดี, มะเร็งเต้านม, โรคตับ, ให้นมบุตร</li><li>แผนการมีบุตรในอนาคต, ความต้องการวางแผนครอบครัว, ความรู้เรื่อง emergency contraception และการป้องกัน STI (ถุงยาง)</li><li>ประวัติท้องไม่พร้อม/คุมกำเนิดล้มเหลว</li></ul>"}
 ],
 pe:[
  {id:"ga", h:"General appearance and vital signs", tag:"", c:"<b>(a) ตรวจอะไร</b>: ลักษณะทั่วไป (ระดับความรู้สึกตัว, ท่าทาง, ท่านอน, หายใจลำบาก, สีผิว ซีด/เหลือง/เขียว, รูปร่าง ผอม/อ้วน, การแต่งกาย, กลิ่น), ความเจ็บป่วย (acutely/chronically ill-looking), <b>Vital signs</b>: BP, PR, RR, BT, SpO2, pain score, น้ำหนัก-ส่วนสูง-BMI<br>ค่าปกติผู้ใหญ่: PR 60-100/min, RR 12-20/min, BP &lt;120/80 mmHg (HT clinic BP ≥140/90), BT oral ~36.5-37.2 C (ไข้ ≥37.8 C), SpO2 ≥95%; BMI (Asian criteria) &lt;18.5 ผอม, 18.5-22.9 ปกติ, 23-24.9 overweight, ≥25 obese (≥30 obese II)<br><b>(b) ขั้นตอน</b><ol><li>ล้างมือ แนะนำตัว ขอ consent ให้ผู้ป่วยนั่งพัก ~5 นาที</li><li><b>BP</b>: นั่งหลังพิงเก้าอี้ เท้าวางพื้น ไม่ไขว่ห้าง แขนเปลือย วางระดับหัวใจ; ขนาดถุงลมยาวคลุม ~80% ความยาว และกว้าง ~40% ของเส้นรอบวงต้นแขน; งดกาแฟ/บุหรี่ 30 นาที; คลำ brachial pulse ใต้ cuff, ปั๊มเกิน SBP ที่หายไปของ radial ประมาณ 30 mmHg, ลดความดัน 2-3 mmHg/วินาที ฟัง Korotkoff phase I (SBP) และ phase V (DBP); ครั้งแรกวัดทั้ง 2 แขน, วัดซ้ำ 2 ครั้ง, orthostatic BP (นอน -&gt; ยืน 1-3 นาที: SBP ลด ≥20 หรือ DBP ลด ≥10 mmHg)</li><li><b>Pulse</b>: คลำ radial 30 วินาที x2 (ไม่สม่ำเสมอนับ 60 วินาที) ดู rate, rhythm, volume</li><li><b>RR</b>: นับขณะแสร้งจับชีพจร 30-60 วินาที ดูความลึก/ใช้กล้ามเนื้อช่วยหายใจ</li><li><b>Temp</b>: oral / axillary / tympanic / rectal (axillary ต่ำกว่า oral ~0.5 C)</li><li><b>SpO2</b>: pulse oximeter ที่นิ้ว (เล็บไม่ทาสี, มือไม่เย็น)</li><li><b>Pain score</b>: numeric rating scale 0-10</li><li>ชั่งน้ำหนัก วัดส่วนสูง (ไม่สวมรองเท้า) คำนวณ BMI = kg/m2; รอบเอว (Asian: ชาย &gt;90, หญิง &gt;80 cm = central obesity)</li></ol>"},
  {id:"skin", h:"Skin, hair and nails", tag:"", c:"<b>(a)</b> ดูสี (pallor, jaundice, cyanosis, flushing, hyperpigmentation), อุณหภูมิ ความชื้น ความยืดหยุ่น (turgor), รอยโรค, ผม-ขน, เล็บ<br>รอยโรคปฐมภูมิ: macule/patch (&lt;1 cm / ≥1 cm เรียบ), papule/plaque (นูน), nodule, vesicle/bulla, pustule, wheal; ทุติยภูมิ: scale, crust, erosion, ulcer, fissure, scar, lichenification. บรรยาย: ตำแหน่ง การกระจาย จำนวน ขนาด รูปร่าง สี ขอบ การเรียงตัว สัมผัส<br>Melanoma <b>ABCDE</b>: Asymmetry, Border, Color, Diameter &gt;6 mm, Evolving.<br>เล็บ: clubbing (Schamroth window หาย, ฐานเล็บ-นิ้วมุม &gt;180), koilonychia (IDA), leukonychia, splinter hemorrhage (IE), Beau's lines, pitting/onycholysis (psoriasis), Terry's nails.<br><b>(b) ขั้นตอน</b><ol><li>ตรวจภายใต้แสงสว่างพอ ในท่านั่ง/นอน เปิดผิวหนังให้เห็นทั้งตัว (พร้อมความเป็นส่วนตัว)</li><li>Inspect ทั่วตัว รวมซอกพับ (รักแร้ ขาหนีบ ใต้เต้านม ระหว่างนิ้ว) หนังศีรษะ ฝ่ามือ-ฝ่าเท้า</li><li>คลำรอยโรค: นุ่ม/แข็ง, เจ็บ, อุณหภูมิ (หลังมือ), blanching (กดด้วยแผ่นแก้ว)</li><li>Turgor: บีบผิวหลังมือ/หน้าอกแล้วปล่อย (กลับ &lt;2 วินาที); capillary refill กดเล็บ 5 วินาที (&lt;2 วินาที)</li><li>ผม/ขน: การกระจาย ความบาง hirsutism; เล็บ: รูปร่าง สี ผิว; ดู clubbing</li><li>ตรวจแผลกดทับ (บริเวณ sacrum, ส้นเท้า) ในผู้ป่วยติดเตียง; ตรวจไฝด้วยกฎ ABCDE</li></ol>"},
  {id:"head", h:"Head and face", tag:"", c:"<b>(a)</b> ศีรษะ: ขนาด รูปร่าง (normocephalic) ความสมมาตร ก้อน แผล กดเจ็บ; ใบหน้า: การแสดงสีหน้า ความสมมาตร ลักษณะผิดปกติ (facies): Cushingoid (moon face), myxedema, acromegaly (กรามยื่น), Parkinsonian (mask-like), nephrotic (ตาบวม), malar rash (SLE), facial palsy; ขมับ (temporal artery - GCA), TMJ, ไซนัส, ต่อมน้ำลาย parotid<br><b>(b) ขั้นตอน</b><ol><li>Inspect ศีรษะ-ใบหน้าจากด้านหน้าและด้านข้าง: สมมาตร, ผิว, ขน/ผม, ลักษณะผิดปกติ</li><li>คลำศีรษะ: ไล่ด้วยปลายนิ้วเป็นวงเล็กทั่ว scalp (หาก้อน, เจ็บ, รอยบุ๋ม)</li><li>คลำ temporal artery ข้างหู: เจ็บ แข็ง ไม่เต้น (giant cell arteritis)</li><li>TMJ: วางนิ้วหน้าหู ให้อ้า-หุบปาก ฟังเสียงคลิก ดูการเบี่ยง; อ้าปากได้ ≥3 นิ้ว</li><li>ไซนัส: กดเคาะ frontal (เหนือคิ้ว) และ maxillary (ใต้เบ้าตา) เจ็บหรือไม่</li><li>Parotid / submandibular gland: คลำด้านหน้าใบหู และใต้กราม; ดู facial swelling</li><li>ทดสอบความสมมาตรของการเคลื่อนไหวใบหน้า (ยกคิ้ว หลับตา ยิ้ม) - รายละเอียดใน CN VII</li></ol>"},
  {id:"eyes", h:"Eyes", tag:"", c:"<b>(a)</b> Visual acuity, visual fields, EOM, pupils, external eye, fundus.<br>ปกติ: acuity 6/6 (20/20); pupil กลม เท่ากัน 3-5 mm, PERRLA (Pupils Equal, Round, Reactive to Light and Accommodation); visual field เต็ม; EOM เต็มไม่มี nystagmus; optic disc ขอบชัด สีชมพูส้ม cup:disc ≤0.5; อัตราส่วน artery:vein ประมาณ 2:3; macula ไม่มี exudate/hemorrhage<br><b>(b) ขั้นตอน</b><ol><li><b>Visual acuity</b>: Snellen chart ระยะ 6 m (หรือ Rosenbaum near card 14 นิ้ว / 35 cm) ทีละตา ปิดอีกข้างด้วยฝ่ามือ (ใส่แว่นเดิม หรือ pinhole); ถ้าอ่านไม่ได้ -&gt; นับนิ้ว (CF) -&gt; มือโบก (HM) -&gt; แยกแสง (LP)</li><li><b>Visual fields (confrontation)</b>: ผู้ตรวจนั่งตรงข้าม ห่าง ~1 m ผู้ป่วยปิดตาข้างหนึ่ง ผู้ตรวจปิดตาข้างตรงข้าม, ให้จ้องจมูกผู้ตรวจ, ขยับนิ้วในขอบ 4 quadrant เข้าหากลาง ให้บอกเมื่อเห็น เทียบกับผู้ตรวจ</li><li><b>External</b>: เปลือกตา (ptosis, lid lag, xanthelasma), conjunctiva (pallor ดึง lower lid, injection), sclera (icterus), cornea (arcus), iris</li><li><b>EOM</b>: ให้มองตามนิ้วเป็นรูป H (6 cardinal positions) หา diplopia, nystagmus, lag; convergence</li><li><b>Pupils</b>: ห้องสลัว ไฟฉายส่องจากด้านข้าง -&gt; direct และ consensual reflex; swinging flashlight test หา RAPD; accommodation reflex (มองไกล -&gt; มองนิ้วใกล้ 10 cm: pupil หด + converge)</li><li><b>Fundoscopy</b>: ห้องมืด ผู้ป่วยมองวัตถุไกล; ตรวจตาขวาของผู้ป่วยด้วยตาขวาของผู้ตรวจ ถือด้วยมือขวา (ตาซ้ายใช้ตาซ้าย-มือซ้าย); เริ่มห่าง ~15 cm ที่ 0 diopter ดู red reflex แล้วเข้าใกล้ ~2-3 cm (เอียง 15 องศาด้านนอก); หมุน lens ชัดโฟกัส; ตามหลอดเลือดเข้าหา optic disc: ดู ขอบ สี cup:disc ratio; หลอดเลือด (AV nicking, narrowing); retina (hemorrhage, exudates); macula (ห่างไปด้านขมับ ~2 disc diameters); papilledema = disc ขอบเบลอ นูน</li></ol>"},
  {id:"ent", h:"Ears, nose, throat and oral cavity", tag:"", c:"<b>(a)</b> หู: ใบหู, ช่องหู, แก้วหู; การได้ยิน; จมูก; ช่องปาก-คอหอย.<br>แก้วหูปกติ: pearly gray, translucent, <b>cone of light</b> ที่ antero-inferior, เห็น handle of malleus และ pars tensa/flaccida. Rinne ปกติ: AC &gt; BC (positive). Weber ปกติ: ไม่เอียง.<br><b>(b) ขั้นตอน</b><ol><li><b>หูภายนอก</b>: ดูใบหู ผิว ก้อน tophi; กดเจ็บ tragus (otitis externa) และ mastoid (mastoiditis)</li><li><b>Otoscopy</b>: ผู้ใหญ่ดึงใบหูขึ้น-หลัง (เด็ก &lt;3 ปี ดึงลง-หลัง) ถือ otoscope แบบดินสอ พิงมือกับแก้ม; ดูช่องหู (cerumen, discharge, ผิวแดง) และแก้วหู (bulging, retraction, perforation, effusion)</li><li><b>การได้ยิน</b>: กระซิบ/ถูนิ้วใกล้หู; <b>Rinne</b> (tuning fork 512 Hz บน mastoid vs หน้าหู); <b>Weber</b> (กลางหน้าผาก): conductive -&gt; ได้ยินดังข้างที่เสีย; sensorineural -&gt; ได้ยินดังข้างดี</li><li><b>จมูก</b>: ดูรูปร่าง ลมหายใจผ่านแต่ละข้าง (ปิดรูข้างหนึ่ง); เงยหน้าส่อง nasal speculum/otoscope: mucosa (ซีด บวม=allergy, แดง=infection), septum deviation/perforation, turbinate, polyp, เลือดออก</li><li><b>ช่องปาก</b>: ไฟฉาย + tongue depressor; ริมฝีปาก, buccal mucosa (Stensen duct ตรงฟันกรามบนซี่ที่ 2), เหงือก, ฟัน, ลิ้น (ด้านบน/ใต้/ขอบ), floor of mouth (Wharton duct), palate แข็ง/อ่อน</li><li><b>คอหอย</b>: ให้ร้อง 'อ้า' -&gt; soft palate ยก uvula อยู่กลาง; ดู tonsils (ขนาด grade 0-4, exudate), posterior pharyngeal wall (cobblestone, แดง)</li><li>คลำต่อมน้ำลาย-ลิ้น (ถ้าสงสัยก้อน) ด้วยถุงมือ; ตรวจกลิ่นปาก</li></ol>"},
  {id:"neck", h:"Neck (thyroid, trachea, JVP)", tag:"", c:"<b>(a)</b> ก้อน หลอดลม ต่อมไทรอยด์ (ขนาด ผิว ความแข็ง ก้อน เคลื่อนตามการกลืน) หลอดเลือดแดง carotid และ <b>JVP</b>.<br>JVP ปกติ: ยอดของ IJV pulsation ≤3 cm เหนือ sternal angle (ผู้ป่วยทำมุม 30-45 องศา) = CVP ≤8 cm H2O (sternal angle สูงจาก RA ประมาณ 5 cm). IJV pulse: เห็นไม่คลำได้, 2 คลื่น (a, v), เปลี่ยนตามหายใจ/ท่า, กดที่ฐานคอแล้วหาย.<br><b>(b) ขั้นตอน</b><ol><li>Inspect: คอตรง ก้อน แผลเป็น (thyroidectomy) เส้นเลือดโป่ง; สังเกตให้ผู้ป่วยกลืนน้ำ: ก้อนไทรอยด์เคลื่อนขึ้นตามการกลืน</li><li><b>Trachea</b>: นิ้วชี้วางใน suprasternal notch ตรงกลาง เลื่อนไปด้านข้างเทียบ 2 ข้างว่าช่องว่างเท่ากัน</li><li><b>Thyroid จากด้านหลัง</b>: ผู้ตรวจยืนหลัง ปลายนิ้วทั้งสองข้างวางต่ำกว่า cricoid cartilage, ให้ผู้ป่วยกลืนน้ำ, คลำ isthmus แล้วคลำ lobe ทีละข้างโดยเอียงศีรษะไปข้างนั้นและดัน trachea ไปด้านนั้น; บรรยาย: ขนาด (diffuse/nodular), ผิว, consistency, เจ็บ, เคลื่อนตามกลืน; ฟัง bruit (Graves'); ตรวจ Pemberton sign ถ้า retrosternal goiter (ยกแขนเหนือศีรษะ - หน้าแดง)</li><li><b>Thyroid จากด้านหน้า</b>: ผู้ตรวจยืนหน้า นิ้วหัวแม่มือกดข้างๆ หลอดลม คลำ lobe คู่กับนิ้วอื่นที่คลำหลัง SCM; ดู WHO goiter grade: 0 ไม่เห็น/ไม่คลำ, 1 คลำได้แต่ไม่เห็น, 2 เห็นได้</li><li><b>JVP</b>: ผู้ป่วยนอนหัวสูง 30-45 องศา หันหน้าเล็กน้อยออกจากข้างที่ตรวจ แสงส่องเฉียง; หา IJV pulsation (ขวา), วัดแนวตั้งจาก sternal angle ถึงยอดคอลัมน์เลือด; ทำ <b>abdominojugular reflux</b> (กดท้อง 10 วินาที)</li><li><b>Carotid</b>: คลำทีละข้าง (ห้ามพร้อมกัน), ฟัง bruit ด้วย diaphragm ขณะกลั้นหายใจ</li></ol>"},
  {id:"ln", h:"Lymph nodes (all groups)", tag:"", c:"<b>(a)</b> ต่อมน้ำเหลืองที่ต้องตรวจ: <b>ศีรษะ-คอ</b> preauricular, posterior auricular, occipital, tonsillar (jugulodigastric), submandibular, submental, superficial cervical (หน้า SCM), posterior cervical (ขอบหน้า trapezius), deep cervical, <b>supraclavicular</b> (Virchow's node ซ้าย = ท้อง/GI cancer), infraclavicular; <b>axillary</b> (central, pectoral/anterior, subscapular/posterior, lateral, apical); <b>epitrochlear</b>; <b>inguinal</b> (horizontal ขนานกับ inguinal ligament, vertical ตามเส้นเลือด saphenous); popliteal.<br>บรรยาย: ตำแหน่ง ขนาด (cm), จำนวน, ผิว, ความแข็ง (soft / firm / hard-rubbery), กดเจ็บ, เคลื่อนไหว/ติดกัน (matted) หรือติดแน่น (fixed), สีผิวด้านบน. โดยทั่วไปต่อมปกติ &lt;1 cm นุ่ม เคลื่อนได้ ไม่เจ็บ. เจ็บ = มักอักเสบ; แข็ง-ติดแน่น-ไม่เจ็บ = สงสัยมะเร็ง.<br><b>(b) ขั้นตอน</b><ol><li>ผู้ป่วยนั่งผ่อนคลาย ปลายนิ้ว 2-3 นิ้ว คลำเป็นวงเล็กๆ นุ่มนวล</li><li>ศีรษะ-คอ ลำดับ: preauricular -&gt; posterior auricular -&gt; occipital -&gt; tonsillar -&gt; submandibular -&gt; submental -&gt; anterior cervical chain -&gt; posterior cervical chain -&gt; supraclavicular (ให้นั่งก้มเล็กน้อย/ยกไหล่หรือหายใจเข้าลึก)</li><li>รักแร้: ผู้ตรวจรองรับแขนผู้ป่วย (relax) -&gt; มือตรงข้ามคลำ central ที่ apex ของรักแร้แล้วไล่ anterior, posterior, lateral</li><li>Epitrochlear: งอข้อศอก 90 องศา ผู้ตรวจจับมือ คลำร่องเหนือ medial epicondyle</li><li>Inguinal: นอนหงาย คลำ horizontal group ใต้ inguinal ligament และ vertical group; Popliteal: งอเข่าเล็กน้อยคลำ popliteal fossa</li><li>เมื่อพบต่อมโต ตรวจ <b>บริเวณที่ระบาย</b> (drainage area) เช่น หนังศีรษะ คอหอย เต้านม ผิวหนัง; ตรวจตับ ม้ามโตร่วม</li></ol>"},
  {id:"breast", h:"Breast and axilla", tag:"", c:"<b>(a)</b> เต้านม 2 ข้าง ขนาด/สมมาตร ผิว (dimpling, peau d'orange, ผื่น/แผลที่หัวนม - Paget's), หัวนม (retraction, discharge), ก้อน; ต่อมรักแร้. ควรมี <b>chaperone</b> ทุกครั้งในผู้ตรวจชาย. เต้านมแบ่ง 4 quadrant + nipple/areola + <b>axillary tail (Spence)</b>.<br><b>(b) ขั้นตอน</b><ol><li>Inspection ท่านั่ง: แขนข้างลำตัว -&gt; ยกแขนเหนือศีรษะ -&gt; มือเท้าสะเอวกดแรง (ตึงกล้ามเนื้อ pectoral) -&gt; โน้มตัวไปข้างหน้า; ดูสมมาตร รูปร่าง ผิว หัวนม; สังเกตรอยบุ๋ม (dimpling) หรือหัวนมดึงรั้งที่ชัดขึ้นเมื่อเปลี่ยนท่า</li><li>Palpation ท่านอนหงาย ยกแขนข้างที่ตรวจไว้เหนือศีรษะ (หมอนใต้ไหล่ข้างนั้น); ใช้ pad ของ 3 นิ้ว (index-middle-ring) กดแรง 3 ระดับ (เบา-กลาง-ลึก)</li><li>รูปแบบการคลำ: vertical strip (แนะนำ), ไล่จาก clavicle ถึง inframammary fold และ sternum ถึง mid-axillary line (รวม axillary tail); หรือ spiral/wedge</li><li>เมื่อพบก้อน: ระบุตำแหน่ง (นาฬิกา และระยะห่างจากหัวนม cm), ขนาด, รูปร่าง, ผิว, ความแข็ง, เจ็บ, เคลื่อนไหว (mobile / fixed to skin/chest wall)</li><li>บีบหัวนมเบาๆ ดู discharge (เลือด, ใส, ขุ่น)</li><li>ตรวจรักแร้ท่านั่ง รองรับแขน ตรวจ 5 กลุ่มของต่อมน้ำเหลือง</li><li>เต้านมชาย: gynecomastia; สอนการตรวจเต้านมด้วยตนเอง (BSE) และแนะนำการคัดกรอง</li></ol>"},
  {id:"cv", h:"Cardiovascular", tag:"", c:"<b>(a)</b> ตรวจ peripheral (pulse, BP, JVP, edema, hands), precordium: inspection, palpation, auscultation.<br>ปกติ: apex beat ที่ <b>5th ICS ที่/ด้านในของ MCL</b>, เส้นผ่านศูนย์กลาง &lt;2.5 cm; S1 ดังที่ apex, S2 ดังที่ base, S2 split ตอนหายใจเข้า<br>Murmur Levine grade 1-6 (1 = ได้ยินเบามาก, 2 = เบาแต่ได้ยินทันที, 3 = ดังปานกลาง, 4 = ดัง + thrill, 5 = ดังมาก ฟังโดยขอบ stethoscope แตะอก, 6 = ได้ยินโดยไม่แตะอก)<br><b>(b) ขั้นตอน</b><ol><li>ผู้ป่วยนอนหงาย ศีรษะสูง 30-45 องศา ถอดเสื้อ (ผู้หญิงคลุมผ้า); ผู้ตรวจยืนด้านขวา</li><li><b>Pulse</b>: radial (rate, rhythm - regularly/irregularly irregular), brachial/carotid (character, volume), radio-femoral delay; ฟัง carotid bruit; ดู JVP; BP</li><li><b>Inspection</b>: รูปร่างอก, scars, pulsation (apex), pectus, สีผิว/ cyanosis, peripheral signs (clubbing, splinter hemorrhage, Osler/Janeway, xanthelasma, edema)</li><li><b>Palpation</b>: (1) <b>Apex beat</b> ตำแหน่ง/ขนาด/ชนิด (heaving, tapping, thrusting); (2) <b>Parasternal heave</b> (ส้นมือวางที่ left sternal edge); (3) <b>Thrills</b> ด้วยส่วนหน้ามือ/ฝ่ามือ ที่ aortic, pulmonic, mitral, tricuspid; (4) palpable P2</li><li><b>Auscultation</b> ในจุด: <b>Aortic</b> (2nd ICS ขวา), <b>Pulmonic</b> (2nd ICS ซ้าย), <b>Erb's</b> (3rd ICS ซ้าย), <b>Tricuspid</b> (4th-5th ICS left lower sternal border), <b>Mitral/apex</b> (5th ICS MCL). Diaphragm ฟัง S1, S2, murmur ความถี่สูง; <b>Bell</b> ฟัง S3, S4, MS murmur. ฟังพร้อมคลำ carotid pulse เพื่อแยก S1/S2 และ systole/diastole</li><li><b>Maneuvers</b>: นอนตะแคงซ้าย + bell ที่ apex ฟัง MS; นั่งโน้มตัวไปข้างหน้า กลั้นหายใจหลังหายใจออก (diaphragm ที่ left sternal border) ฟัง AR; inspiration เพิ่ม murmur ด้านขวา (Carvallo); Valsalva/ยืนลด murmur ส่วนใหญ่ แต่เพิ่ม HOCM; squatting/handgrip เพิ่ม MR, VSD, AR; handgrip ลด AS/HOCM</li><li>บรรยาย murmur: timing (systolic/diastolic), ตำแหน่ง, radiation (AS -&gt; carotid; MR -&gt; axilla), grade, pitch, shape, quality; ฟังปอด base ดู crackles, ตรวจตับโต, ตรวจ pitting edema และ sacral edema</li><li><b>Peripheral pulses</b>: radial, brachial, carotid, femoral, popliteal, dorsalis pedis, posterior tibial - เทียบ 2 ข้าง</li></ol>"},
  {id:"resp", h:"Respiratory", tag:"", c:"<b>(a)</b> สังเกตการหายใจ รูปร่างทรวงอก ผลการคลำ เคาะ ฟัง ทั้งหน้า-หลัง-ข้าง. ตำแหน่ง: lung apex สูงกว่า clavicle 3-4 cm; ขอบล่างปอด 6th rib (MCL), 8th rib (MAL), 10th rib (หลัง); oblique fissure จาก T3 ถึง 6th rib ที่ MCL; horizontal fissure ที่ 4th rib ถึง 5th rib ที่ MAL.<br>ผล: <b>consolidation</b> = dull, tactile fremitus/vocal resonance เพิ่ม, bronchial breathing, crackles; <b>pleural effusion</b> = stony dull, fremitus/breath sounds ลด; <b>pneumothorax</b> = hyperresonant, breath sounds ลด, trachea เบี่ยง (tension); <b>COPD</b> = barrel chest, hyperresonant, breath sounds ลด, wheeze; <b>fibrosis</b> = fine end-inspiratory crackles.<br><b>(b) ขั้นตอน</b><ol><li><b>Inspection</b>: RR, ความลึก, pattern, accessory muscles, intercostal retraction, pursed-lip breathing; รูปร่างอก (barrel, pectus excavatum/carinatum, kyphoscoliosis), scars, ผื่น; ดูมือ (clubbing, nicotine stain, cyanosis, <b>asterixis</b>/CO2 flap), trachea, JVP</li><li><b>Palpation</b>: กดเจ็บ; <b>chest expansion</b> วางนิ้วโป้งชิดกันที่ T10 ด้านหลัง (หรือชายโครงด้านหน้า) แผ่นิ้วที่ผิวข้าง ให้หายใจเข้าลึกแล้วดูนิ้วโป้งแยกจากกันเท่ากันทั้งสองข้าง (ปกติ ≥3-5 cm)</li><li><b>Tactile fremitus</b>: วางด้านข้างมือ/ฝ่ามือ ให้พูด 'หนึ่ง-หนึ่ง-หนึ่ง' (one-one-one / ninety-nine) เปรียบเทียบซ้ายขวา ไล่ลงทีละระดับ</li><li><b>Percussion</b>: วางนิ้วกลางมือซ้ายราบไปกับช่องซี่โครง เคาะที่ DIP ด้วยปลายนิ้วกลางมือขวา; เปรียบเทียบซ้าย-ขวาเป็นแบบ zigzag; resonant / dull / stony dull / hyperresonant; ตรวจ diaphragmatic excursion ด้านหลัง (ปกติ 3-5 cm)</li><li><b>Auscultation</b>: ใช้ diaphragm ให้หายใจเข้า-ออกลึกทางปาก เปรียบเทียบซ้าย-ขวาทีละตำแหน่ง ครบ posterior, lateral, anterior; breath sound: vesicular (ปกติ), bronchovesicular, bronchial; adventitious: crackles (fine/coarse), wheeze, rhonchi, stridor, pleural rub</li><li><b>Vocal resonance</b>: ฟังให้พูด 99 - bronchophony, whispered pectoriloquy, egophony (E-&gt;A)</li><li>Special: ตรวจ trachea เบี่ยง, Hoover's sign, peak flow, forced expiratory time, ตรวจขา (DVT) ถ้าสงสัย PE</li></ol>"},
  {id:"abd1", h:"Abdomen (1): inspection, auscultation, percussion", tag:"", c:"<b>(a)</b> ลำดับ <b>IAPP</b> (Inspection, Auscultation, Percussion, Palpation) - ฟังก่อนเคาะ/คลำ เพราะการกดทำให้ bowel sound เปลี่ยน. แบ่งท้อง 4 quadrant (RUQ, LUQ, RLQ, LLQ) หรือ 9 regions. ผู้ป่วยนอนหงาย หมอนใต้ศีรษะ แขนข้างลำตัว เข่างอเล็กน้อย เปิดจาก xiphoid ถึง pubic symphysis, ปัสสาวะก่อน, มือผู้ตรวจอุ่น, ถามจุดเจ็บและตรวจจุดนั้นเป็นอันสุดท้าย.<br><b>(b) ขั้นตอน</b><ol><li><b>Inspection</b> (จากข้างเตียง/ปลายเตียง): contour (flat, scaphoid, distended - '5Fs': Fat, Fluid, Flatus, Feces, Fetus), สมมาตร, สะดือ (everted ใน ascites; Sister Mary Joseph node), ผิว (scars, striae, สีเหลือง, spider nevi, <b>caput medusae</b>, เส้นเลือดโป่ง - ทิศทางการไหล), <b>Cullen/Grey-Turner</b> (pancreatitis), การเคลื่อนไหวตามหายใจ, visible peristalsis, pulsation, hernia (ให้ไอ/ยกศีรษะ)</li><li><b>Auscultation</b>: diaphragm วางที่ RLQ (หรือใต้สะดือ) ฟังนานราว 1 นาทีก่อนสรุปว่า absent; bowel sounds ปกติ ~5-34 ครั้ง/นาที; ฟัง <b>bruit</b> ที่ aorta (เหนือสะดือ), renal arteries (ข้าง midline), iliac, femoral; hepatic friction rub, venous hum</li><li><b>Percussion</b> ทั่ว 4 quadrant: tympany เหนือลำไส้, dullness เหนือ organ/ก้อน/ของเหลว; ปัสสาวะค้างเคาะเหนือ pubic symphysis (suprapubic dullness)</li><li><b>Liver span</b>: เคาะที่ right MCL จากเหนือ (ปอด resonant) ลงมาจนเริ่ม dull = upper border; แล้วเคาะจากล่าง (tympany) ขึ้นไปจนเริ่ม dull = lower border; วัดความยาว (ปกติ ~6-12 cm ที่ MCL; ชายมากกว่าหญิง); ตรวจ liver scratch test (ถ้าจำเป็น)</li><li><b>Spleen percussion</b>: Castell's sign - เคาะช่องซี่โครงล่างสุดบริเวณ left anterior axillary line (8th-9th ICS) - ปกติ resonant; dull เมื่อหายใจเข้า = splenomegaly; Traube's space</li><li><b>Shifting dullness</b>: เคาะจาก umbilicus (tympany) ไปด้านข้างจนเปลี่ยนเป็น dull -&gt; ทำเครื่องหมาย -&gt; ให้ผู้ป่วยตะแคงไปด้านนั้นรอ ~30 วินาที -&gt; เคาะซ้ำ: ถ้า dullness ย้ายเป็น tympany แสดงว่ามี free fluid (positive)</li><li><b>Fluid thrill</b>: ให้ผู้ช่วย (หรือผู้ป่วย) วางขอบมือกดกลางท้อง, ผู้ตรวจวางมือหนึ่งที่ flank ข้างหนึ่ง แล้วเคาะที่ flank อีกข้าง ดูคลื่นกระทบ (ต้อง ascites ปริมาณมาก)</li></ol>"},
  {id:"abd2", h:"Abdomen (2): palpation, organomegaly and special signs", tag:"", c:"<b>(a)</b> คลำตื้น (superficial) -&gt; ลึก (deep) ดู tenderness, guarding (voluntary vs involuntary), rigidity (board-like = peritonitis), rebound, ก้อน, อวัยวะโต.<br><b>(b) ขั้นตอน</b><ol><li>นั่งข้างขวาของผู้ป่วย พูดคุยให้ผ่อนคลาย ดูสีหน้าตลอด; เริ่มคลำ <b>ห่างจากจุดเจ็บ</b></li><li><b>Light palpation</b> ทั้ง 9 regions ด้วยปลายนิ้วเรียบ หา tenderness, guarding, ก้อนผิวเผิน; <b>Deep palpation</b> หา ก้อน ขนาด ผิว ความแข็ง เคลื่อนตามหายใจ เต้นหรือไม่ (pulsatile)</li><li><b>ตับ</b>: วางมือขวา (นิ้วขนาน midline) ที่ RLQ ห่างจาก costal margin; ให้หายใจเข้าลึกพร้อมเลื่อนมือขึ้นเรื่อยๆ จนสัมผัสขอบตับ; บรรยายขอบ (sharp/rounded), ผิว (smooth/nodular), ความแข็ง, เจ็บ, pulsatile; วัดระยะใต้ right costal margin ที่ MCL; แยกจาก ptosis ตับด้วย percussion span</li><li><b>ม้าม</b>: เริ่มจาก RIF (ไกลๆ) เลื่อนเฉียงขึ้นไป left costal margin; มือซ้ายรองประคองซี่โครงซ้ายล่าง; ให้หายใจลึก; ถ้าไม่พบ ให้นอนตะแคงขวา (right lateral decubitus) แล้วคลำซ้ำ; ม้ามโตขยายเฉียงมาทาง RIF; มี notch ได้</li><li><b>ไต (bimanual ballottement)</b>: มือหนึ่งรองใต้ flank (หลัง) อีกมือกดด้านหน้า ดันขึ้น-ลงจับ ballot; ไตขวาล่าง (lower pole) อาจคลำได้ในคนผอม; ไตซ้ายปกติคลำไม่ได้. CVA tenderness: กำปั้นทุบเบาๆ มุม costovertebral</li><li><b>Aorta</b>: กดลึกเหนือสะดือ ใช้ 2 มือแยก 2 ข้างของ pulsation ดูว่าขยายออกด้านข้าง (expansile) = AAA; ปกติเส้นผ่านศูนย์กลาง &lt;3 cm</li><li><b>Murphy's sign</b>: นิ้วหรือฝ่ามือกดใต้ right costal margin ที่ MCL (จุดตับ-ถุงน้ำดี) ให้หายใจเข้าลึก; หยุดหายใจเข้ากะทันหัน เพราะเจ็บ = positive (acute cholecystitis). Courvoisier's law: ถุงน้ำดีโตคลำได้ + ตัวเหลืองไม่เจ็บ -&gt; สงสัยมะเร็ง (ไม่ใช่นิ่ว)</li><li><b>Appendicitis</b>: <b>McBurney's point</b> (1/3 จาก right ASIS ถึงสะดือ) กดเจ็บ; <b>Rovsing's sign</b> (กดที่ LLQ แล้วเจ็บที่ RLQ); <b>Psoas sign</b> (นอนตะแคงซ้าย เหยียดสะโพกขวาไปหลัง หรือยกต้นขาขวาต้านมือ); <b>Obturator sign</b> (งอสะโพก-เข่า 90 องศา แล้วหมุนสะโพกเข้าใน - internal rotation)</li><li><b>Rebound tenderness</b> (Blumberg): กดช้าๆ ลึก แล้วปล่อยเร็ว เจ็บตอนปล่อย = peritoneal irritation (วิธีอ่อน: เคาะเบาๆ percussion tenderness / ให้ไอ)</li><li>ตรวจท้องจบด้วย hernia orifices, ตรวจ DRE/genitalia ตามข้อบ่งชี้</li></ol>"},
  {id:"hernia", h:"Hernia and external genitalia (male)", tag:"", c:"<b>(a)</b> ตรวจขาหนีบ ถุงอัณฑะ องคชาต. Inguinal hernia: ก้อนอยู่ <b>เหนือและมาทางกลางของ pubic tubercle</b>; Femoral hernia: <b>ใต้และห่างออกด้านข้างของ pubic tubercle</b>. ตำแหน่ง deep inguinal ring = จุดกึ่งกลางระหว่าง ASIS และ pubic symphysis (mid-inguinal point), superficial ring อยู่เหนือและด้านนอกของ pubic tubercle. Indirect hernia ผ่าน deep ring ลงสู่ scrotum ได้; direct hernia ออกทางผนังด้านหลังของ inguinal canal (Hesselbach's triangle).<br><b>(b) ขั้นตอน</b><ol><li>แนะนำ ขอ consent; ผู้ตรวจสวมถุงมือ; ผู้ป่วยยืน (และนอนหงาย) เปิดท่อนล่าง</li><li><b>Inspection ท่ายืน</b>: ดูก้อนที่ขาหนีบ/scrotum, ให้ไอหรือเบ่ง (Valsalva) เปรียบเทียบสองข้าง; ผิวถุงอัณฑะ (erythema, ulcer), องคชาต: ดู foreskin (phimosis, paraphimosis), glans, urethral meatus (discharge, hypospadias), แผล/ผื่น/ไฝ/หูด</li><li><b>Palpation ก้อนที่ขาหนีบ</b>: บรรยาย ตำแหน่ง ขนาด รูปร่าง ผิว ความแข็ง เจ็บ, reducible?, cough impulse, bowel sound</li><li><b>Invaginate scrotum</b>: ใช้ index finger ดันผิว scrotum ขึ้นตาม spermatic cord ไปถึง external ring ให้ไอ ดู impulse ที่ปลายนิ้ว</li><li><b>Deep ring occlusion test</b>: หลัง reduce ก้อน กดที่ deep ring ให้ไอ - ถ้าไม่ออกมา = indirect; ถ้าออกมา = direct</li><li><b>ถุงอัณฑะ</b>: คลำ testis แต่ละข้างด้วยหัวแม่มือ-นิ้วชี้: ขนาด (ปริมาตรปกติ 15-25 mL; ยาว 4-5 cm), ความแข็ง (เรียบ ยางหยุ่น), กดเจ็บ, ก้อน; epididymis ที่ด้านหลัง; vas deferens (เหมือนเส้นเชือก 'spaghetti'); ถ้าไม่เห็น testis ในถุง คลำตามแนว inguinal canal</li><li><b>Hydrocele</b>: ไม่เจ็บ, 'can get above the swelling', ส่องไฟ (transillumination) ผ่านแสง; <b>Varicocele</b> ('bag of worms', ยืนและ Valsalva ชัดขึ้น, ยุบเมื่อนอน); Spermatocele; Testicular torsion: เจ็บมาก, testis สูงและนอนขวาง, <b>cremasteric reflex</b> (ลูบต้นขาด้านใน L1-2) หาย; epididymo-orchitis: Prehn's sign</li><li>ตรวจ Tanner stage ถ้ามีข้อบ่งชี้ (เด็ก/วัยรุ่น)</li></ol>"},
  {id:"dre", h:"Digital rectal examination (DRE)", tag:"", c:"<b>(a)</b> ตรวจรอบทวารหนัก, sphincter tone, ผนังทวารหนัก, ต่อมลูกหมาก (ชาย) / ปากมดลูก (หญิง), สีอุจจาระบนถุงมือ. ปกติ: ต่อมลูกหมากขนาดเท่าลูกวอลนัท ~4 cm มี 2 lobes มี median sulcus ผิวเรียบ ยางหยุ่น ไม่เจ็บ; seminal vesicles คลำไม่ได้. BPH: ใหญ่ เรียบ ร่องกลางหาย; มะเร็ง: แข็งเป็นก้อนผิวขรุขระไม่สมมาตร.<br><b>(b) ขั้นตอน</b><ol><li>อธิบายขั้นตอน ขอ consent, มี <b>chaperone</b>, ปิดม่าน; ผู้ตรวจสวมถุงมือ</li><li>ท่า <b>left lateral (Sims')</b> งอสะโพก-เข่า ก้นชิดขอบเตียง (หรือ knee-chest / lithotomy)</li><li><b>Inspection</b>: แยกก้น ดูผิวรอบ anus - fissure, fistula, external hemorrhoid, skin tag, prolapse (ให้เบ่ง), pilonidal sinus, perianal abscess, warts, ผื่น, เลือด</li><li>หล่อลื่นนิ้วชี้ ถุงมือ; วางปลายนิ้วเบาๆ ที่ anus ให้ผู้ป่วยหายใจลึกๆ แล้วเบ่งเบาๆ; สอดนิ้วช้าๆ เมื่อ sphincter คลาย</li><li><b>ประเมิน anal sphincter tone</b> ขณะพัก และขณะให้เบ่งหรือเกร็ง (squeeze); ตรวจ anal canal มีก้อน/เจ็บ</li><li><b>ตรวจผนัง rectum</b> หมุนนิ้ว 360 องศา (ก้อน, polyp, ขรุขระ, เจ็บ), anterior wall: <b>prostate</b> (ขนาด, ผิว, ความแข็ง, ร่อง, กดเจ็บ), seminal vesicles; ผู้หญิง: cervix, retroverted uterus, pouch of Douglas</li><li>ถอดนิ้วออก ตรวจสี <b>อุจจาระที่ติดถุงมือ</b> (เลือดสด, melena ดำเหนียวกลิ่นเหม็น, mucus, pus, สีซีด); ทำ fecal occult blood ถ้ามีข้อบ่งชี้</li><li>เช็ดทำความสะอาดให้ผู้ป่วย; ทิ้งถุงมือ; แจ้งผล; บันทึก tone, prostate, อุจจาระ</li></ol>"},
  {id:"pv", h:"Peripheral vascular (arterial, venous, edema, DVT)", tag:"", c:"<b>(a)</b> <b>Arterial</b>: สี อุณหภูมิ ขน แผล (ulcer arterial: ปลายเท้า/ขอบนอก, punched-out, เจ็บ; venous: เหนือตาตุ่มใน, ตื้น ขอบไม่เรียบ), capillary refill, pulses. ระดับ pulse: 0 = absent, 1+ = diminished, 2+ = normal, 3+ = increased, 4+ = bounding. <b>ABI</b> = SBP ankle (สูงสุดของ DP/PT) / SBP brachial (สูงสุดของสองแขน) ด้วย Doppler: 1.0-1.4 ปกติ; 0.91-0.99 borderline; ≤0.90 PAD; &lt;0.4 critical limb ischemia; &gt;1.4 non-compressible (calcified เช่น DM).<br><b>Edema</b> (กดนาน ≥5 วินาที เหนือกระดูก tibia/medial malleolus): 1+ ≈ 2 mm ยุบเร็ว, 2+ ≈ 4 mm, 3+ ≈ 6 mm (ยุบได้ใน ~1 นาที), 4+ ≈ 8 mm (นาน 2-5 นาที).<br><b>(b) ขั้นตอน</b><ol><li><b>Arterial pulses</b> ทั้ง 2 ข้างเทียบกัน: radial, ulnar (Allen's test), brachial, carotid, <b>femoral</b> (ใต้ mid-inguinal point), <b>popliteal</b> (งอเข่า 30 องศา กดลึก 2 มือ), <b>dorsalis pedis</b> (ด้านนอกของ extensor hallucis tendon), <b>posterior tibial</b> (หลัง medial malleolus); ฟัง bruit ที่ femoral/iliac</li><li><b>Buerger's test</b>: ยกขา ~45 องศา 1 นาที (ซีด = ischemia) -&gt; นั่งห้อยขา (สีแดงคล้ำ rubor/reactive hyperemia)</li><li><b>ABI</b>: นอนพัก 10 นาที วัด SBP brachial ทั้งสองแขน แล้ววัด SBP ankle (DP, PT) ด้วย Doppler</li><li><b>Varicose veins</b> (ยืน): ดู ขนาด การกระจาย (long/short saphenous), telangiectasia, ผิวหนัง (hemosiderin, lipodermatosclerosis, eczema, ulcer)</li><li><b>Trendelenburg test</b>: นอนหงาย ยกขา 90 องศา รีดเลือดดำให้แฟบ; กด saphenofemoral junction (ใต้และด้านนอกของ pubic tubercle ~2.5 cm) หรือรัด tourniquet; ให้ยืน -&gt; ดูการเติม: <b>หากเติมเร็วจากด้านล่างขณะยังกด = perforator incompetence; หากเติมเร็วหลังปล่อย = SFJ incompetence</b>. Perthes' test ประเมิน deep vein patency</li><li><b>DVT signs</b>: น่อง/ขาบวมข้างเดียว (วัดเส้นรอบวง 10 cm ใต้ tibial tuberosity ต่างกัน &gt;3 cm), pitting edema ข้างเดียว, กดเจ็บตามแนวหลอดเลือดลึก, superficial collateral veins; Homan's sign (ไม่ไว/ไม่จำเพาะ); ใช้ <b>Wells score</b></li></ol>"},
  {id:"msk1", h:"Musculoskeletal (1): GALS screen and look-feel-move", tag:"", c:"<b>(a) หลักการ</b>: <b>Look</b> (บวม แดง ผิดรูป กล้ามเนื้อลีบ แผล), <b>Feel</b> (อุ่น เจ็บ effusion ก้อน crepitus), <b>Move</b> (active -&gt; passive ROM; ความเจ็บ ความฝืด), + <b>Special tests</b> + function + neurovascular. เปรียบเทียบสองข้างเสมอ; ตรวจข้อเหนือและใต้ข้อที่ผิดปกติ.<br><b>GALS</b> = Gait, Arms, Legs, Spine - screen ใน 1-2 นาที.<br><b>(b) ขั้นตอน GALS</b><ol><li><b>Screening questions</b>: (1) มีอาการปวด/ฝืดของกล้ามเนื้อ ข้อ หรือหลังไหม? (2) แต่งตัวเองลำบากไหม? (3) ขึ้นลงบันไดลำบากไหม?</li><li><b>Gait</b>: ยืนดูจากหน้า-หลัง-ข้างโดยเปิดขา; ให้เดินไป-กลับ หมุนตัว; ดู ความสมมาตร, stride, ปวดขา (antalgic), ยกแขนแกว่ง</li><li><b>Spine</b>: ยืนหันหลัง - ดูระดับไหล่-pelvis, scoliosis, มองด้านข้างดู kyphosis/lordosis; ให้เอียงศีรษะ (ใบหูแตะไหล่), ก้มเอียงข้าง (lateral flexion เลื่อนมือตามขา), ก้มตัวไปข้างหน้าแตะนิ้วเท้า (ดูกระดูกสันหลังโค้งเรียบ)</li><li><b>Arms</b>: ยกมือไว้หลังศีรษะ (shoulder abduction + ER), เหยียดแขนตรงไปด้านหน้า คว่ำมือ-หงายมือ (pronation/supination), กำมือ, บีบนิ้วโป้ง-ชี้ (pincer), เหยียดนิ้ว; metacarpal squeeze (MCP), งอข้อศอก</li><li><b>Legs</b>: ผู้ป่วยนอน - ดูกล้ามเนื้อ; งอสะโพกและเข่า ~90 องศา แล้วหมุนสะโพกเข้า-ออก (internal rotation - ไวที่สุดต่อโรคสะโพก); เข่างอ-เหยียดสุด; patellar tap/ ดู effusion; metatarsal squeeze (MTP); ดูฝ่าเท้า (callus, deformity)</li><li>ถ้าพบความผิดปกติ ตรวจเพิ่มด้วย <b>REMS</b> (Regional Examination of the Musculoskeletal System)</li><li>ตรวจข้อ: ระบุ arthritis (บวม ร้อน แดง เจ็บ ขยับลำบาก) <b>monoarticular vs polyarticular</b>, inflammatory (ฝืดเช้า &gt;30 นาที) vs mechanical</li></ol>"},
  {id:"msk2", h:"Musculoskeletal (2): knee, shoulder, spine and hip", tag:"", c:"<b>(a)</b> ตรวจแบบ look-feel-move + special tests. ROM ปกติ: เข่า flexion ~135-140 องศา extension 0; ไหล่ forward flexion/abduction ~180 องศา; cervical rotation ~80 องศา; lumbar flexion (Schober) เพิ่ม ≥5 cm.<br><b>(b) ขั้นตอน</b><ol><li><b>Knee</b> (ยืน-นอน): look - บวม, alignment (varus/valgus), กล้ามเนื้อ quadriceps ลีบ, แผล; feel - อุ่น, joint line tenderness, effusion: <b>patellar tap</b> (ลูบ suprapatellar pouch ลง กดสะบ้า ดู ballotable) และ <b>bulge/stroke test</b> (ปริมาณน้อย); move - flexion/extension active-passive, crepitus; ligaments: <b>Anterior drawer</b> (เข่างอ 90 องศา ดึงหน้า tibia = ACL), <b>Lachman</b> (เข่างอ 20-30 องศา ไวกว่า), <b>Posterior drawer</b>/sag sign (PCL), <b>Valgus stress</b> (MCL) และ <b>Varus stress</b> (LCL) ที่ 0 และ 30 องศา; meniscus: <b>McMurray's test</b> (งอเข่า-สะโพก หมุน tibia แล้วเหยียดเข่า ฟังเสียงคลิก/เจ็บ), joint line tenderness</li><li><b>Shoulder</b>: look - สมมาตร, กล้ามเนื้อ deltoid/supraspinatus ลีบ; feel - AC joint, bicipital groove, greater tuberosity; move - flexion, extension, abduction (<b>painful arc 60-120 องศา</b> = subacromial impingement), ER, IR (มือแตะหลัง); special tests: <b>Neer / Hawkins-Kennedy</b> (impingement), <b>Empty can / Jobe</b> (supraspinatus), <b>Drop arm</b> (rotator cuff tear), <b>Lift-off / Gerber</b> (subscapularis), ER lag (infraspinatus), <b>Apprehension</b> (anterior instability), Speed's/Yergason (biceps)</li><li><b>Spine</b>: look - alignment (scoliosis, kyphosis, lordosis), feel - spinous processes + paraspinal muscle spasm, กดเจ็บ; move - cervical (flex/ext/rotate/lateral flexion), lumbar flexion (<b>modified Schober</b>: ทำเครื่องหมายที่ L5 และจุด 10 cm เหนือขึ้นไป; ก้มสุดระยะนี้ควรเพิ่มอย่างน้อย 5 cm (&gt;15 cm)); <b>SLR</b> (นอนหงาย ยกขาตรงทีละข้าง; ปวดร้าวใต้เข่า ที่ 30-70 องศา = nerve root L5/S1); crossed SLR; femoral stretch (L2-4); <b>Spurling's</b> (cervical radiculopathy); ตรวจ neuro ขาประกอบ (power, reflex, sensation) และ saddle sensation ถ้าสงสัย cauda equina</li><li><b>Hip</b>: look - ความยาวขา (true: ASIS-medial malleolus; apparent: umbilicus-medial malleolus); move - flexion, IR/ER (ไวสุด), abduction; <b>Thomas test</b> (fixed flexion deformity); <b>Trendelenburg test</b> (ยืนขาเดียว pelvis ตก=gluteus medius อ่อนแรง); <b>FABER</b> (Patrick)</li><li>มือ-ข้อมือ: <b>Phalen's</b> / <b>Tinel's</b> (carpal tunnel), ข้อ DIP/PIP (Heberden/Bouchard), swan-neck, boutonniere, ulnar deviation (RA)</li></ol>"},
  {id:"neu1", h:"Neurological (1): mental status, GCS and cranial nerves", tag:"", c:"<b>(a) Mental status</b>: ระดับความรู้สึกตัว (alert / drowsy / stupor / coma), orientation (time, place, person), attention (serial 7s, spell 'WORLD' backwards, digit span), memory (registration + recall 3 สิ่ง 5 นาที), language (fluency, naming, repetition, comprehension; aphasia - Broca/Wernicke), อารมณ์, ความคิด, insight (MMSE-Thai 2002 / MoCA).<br><b>Glasgow Coma Scale</b> (3-15): <b>E</b> 4 ลืมตาเอง, 3 เรียก, 2 เจ็บ, 1 ไม่ลืม; <b>V</b> 5 oriented, 4 สับสน, 3 คำไม่เป็นประโยค, 2 เสียงไม่เป็นคำ, 1 ไม่มี; <b>M</b> 6 ทำตามสั่ง, 5 localizes, 4 withdraws, 3 flexion (decorticate), 2 extension (decerebrate), 1 ไม่ขยับ. ≤8 = severe (ปกป้องทางเดินหายใจ), 9-12 moderate, 13-15 mild. เขียน E_V_M_.<br><b>(b) Cranial nerves (I-XII)</b><ol><li><b>I Olfactory</b>: ปิดตา ปิดรูจมูกข้างหนึ่ง ดมกลิ่นไม่ระคายเคือง (กาแฟ สบู่ กานพลู) บอกชนิด</li><li><b>II Optic</b>: visual acuity, visual fields (confrontation), fundoscopy, pupillary light reflex (afferent)</li><li><b>III, IV, VI</b>: EOM เป็นรูป H; III: ptosis, pupil dilation, ตากลอกเข้า-ขึ้น-ลง; IV (superior oblique): มองลงเมื่อตากลอกเข้าด้านใน; VI (lateral rectus): มองออกด้านนอก (LR6 SO4); หา diplopia, nystagmus; pupil efferent (III parasympathetic)</li><li><b>V Trigeminal</b>: sensory V1 (หน้าผาก), V2 (แก้ม), V3 (คาง) - light touch + pinprick; motor: กัดฟันคลำ masseter/temporalis, อ้าปากต้าน (คางเบี่ยงไปข้างอ่อนแรง); corneal reflex (V1 afferent - VII efferent); jaw jerk</li><li><b>VII Facial</b>: ยกคิ้ว (UMN: forehead spared; LMN: forehead ผิดปกติ), หลับตาแน่น, ยิ้มโชว์ฟัน, พองแก้ม, ผิวปาก; รสชาติ 2/3 หน้าลิ้น (ถ้าจำเป็น)</li><li><b>VIII Vestibulocochlear</b>: ได้ยิน (กระซิบ, ถูนิ้ว), Rinne/Weber; vestibular: nystagmus, head impulse, Dix-Hallpike</li><li><b>IX, X</b>: ร้อง 'อ้า' - soft palate ยกเท่ากัน, uvula ถูกดึงไปด้านดี (เบี่ยงออกจากข้างที่มีรอยโรค); gag reflex; เสียงแหบ/ไอ; กลืน</li><li><b>XI Accessory</b>: ยักไหล่ต้านมือ (trapezius), หันหน้าต้านมือ (SCM - หันขวาทดสอบ SCM ซ้าย)</li><li><b>XII Hypoglossal</b>: แลบลิ้น - เบี่ยงไป <b>ข้างที่มีรอยโรค</b> (LMN); atrophy, fasciculations; ดันแก้มด้วยลิ้นต้านนิ้ว</li></ol>"},
  {id:"neu2", h:"Neurological (2): motor, sensory and reflexes", tag:"", c:"<b>(a) Motor</b>: bulk, tone, power (MRC), pronator drift, fasciculations. <b>MRC grade</b>: 0 = ไม่มีการหดตัว; 1 = เห็นกล้ามเนื้อกระตุก (flicker); 2 = ขยับได้เมื่อไม่ต้านแรงโน้มถ่วง; 3 = ยกต้านแรงโน้มถ่วงได้; 4 = ต้านแรงผู้ตรวจได้บางส่วน (4-, 4, 4+); 5 = ปกติ. <b>Reflex grade</b>: 0 ไม่มี, 1+ ลดลง, 2+ ปกติ, 3+ ไวขึ้น, 4+ ไวมากมี clonus.<br><b>UMN</b>: spasticity (clasp-knife), hyperreflexia, Babinski +, clonus, ไม่มี atrophy/fasciculation; <b>LMN</b>: flaccid, hyporeflexia, atrophy, fasciculations.<br><b>(b) ขั้นตอน</b><ol><li><b>Inspection</b>: bulk, atrophy, fasciculations, involuntary movements (tremor, chorea)</li><li><b>Tone</b>: จับ passive ข้อมือ/ศอก/เข่า/ข้อเท้าเคลื่อนไหวหลายความเร็ว - spasticity, lead-pipe/cogwheel rigidity (Parkinson's), hypotonia; ankle clonus (&gt;3 beats)</li><li><b>Power</b>: ทดสอบกลุ่มสำคัญ - shoulder abduction (C5, deltoid), elbow flexion (C5-6), elbow extension (C7), wrist extension (C6-7), finger flexion (C8), finger abduction (T1), hip flexion (L2-3), knee extension (L3-4), knee flexion (S1), ankle dorsiflexion (L4-5), plantar flexion (S1-2), big-toe extension (L5); <b>pronator drift</b> (หงายมือยื่นไปข้างหน้า หลับตา 20 วินาที)</li><li><b>Sensory</b>: ปิดตา; <b>spinothalamic</b> - pinprick และ temperature; <b>dorsal column</b> - light touch (สำลี), vibration (tuning fork 128 Hz ที่ bony prominence), joint position sense (big toe/นิ้ว), 2-point; ตรวจเทียบ dermatome: C6 หัวแม่มือ, C7 นิ้วกลาง, C8 นิ้วก้อย, T4 หัวนม, T10 สะดือ, L1 ขาหนีบ, L4 medial malleolus, L5 หลังเท้า, S1 ขอบนอกเท้า, S2-4 รอบทวาร; <b>Romberg test</b> (ยืนชิดเท้า ลืมตา -&gt; หลับตา: เซ = positive, dorsal column)</li><li><b>DTR</b> (reflex hammer ตีที่เอ็น ผู้ป่วยผ่อนคลาย เทียบสองข้าง): biceps C5-6, brachioradialis C5-6, triceps C7, knee jerk L3-4, ankle jerk S1-2; reinforcement ด้วย Jendrassik (ดึงมือ/กัดฟัน)</li><li><b>Plantar response</b>: ขีดฝ่าเท้าด้านนอกจากส้นไปโคนนิ้วก้อยแล้วเลี้ยวไปที่ใต้โคนนิ้วโป้ง - ปกติ นิ้วโป้งงอลง (flexor); <b>Babinski</b> = นิ้วโป้งกระดกขึ้น + นิ้วอื่นแผ่ (UMN; ปกติในทารก &lt;~1-2 ปี)</li><li>Superficial reflexes: abdominal, cremasteric; Hoffmann's sign</li></ol>"},
  {id:"neu3", h:"Neurological (3): cerebellar, gait and meningeal signs", tag:"", c:"<b>(a)</b> Cerebellar: <b>DANISH</b> - Dysdiadochokinesia, Ataxia, Nystagmus, Intention tremor, Slurred (scanning) speech, Hypotonia; ตำแหน่ง: hemisphere = ipsilateral limb ataxia, vermis = truncal ataxia. เดิน: ประเมินชนิด gait. Meningeal irritation: neck stiffness, Kernig, Brudzinski.<br><b>(b) ขั้นตอน</b><ol><li><b>Finger-nose test</b>: แตะจมูกตนเอง -&gt; นิ้วผู้ตรวจ (เปลี่ยนตำแหน่ง) ดู dysmetria / intention tremor</li><li><b>Rapid alternating movements</b>: หมุนคว่ำ-หงายมือ (dysdiadochokinesia) หรือแตะนิ้วโป้ง-ชี้เร็วๆ</li><li><b>Heel-shin test</b>: นอนหงาย เอาส้นเท้าไล้ลงบน shin ตั้งแต่เข่าถึงข้อเท้า (เลียนแบบเส้นตรง); rebound phenomenon</li><li>ดู nystagmus, พูดแบบ scanning, truncal ataxia (นั่งเอง), titubation</li><li><b>Gait</b>: ให้เดินปกติ เดินต่อเท้า (<b>tandem walk</b>), เดินด้วยปลายเท้า-ส้นเท้า, Romberg; ชนิด: <b>spastic/hemiparetic</b> (circumduction), <b>scissor</b>, <b>steppage</b> (foot drop), <b>waddling</b> (proximal myopathy), <b>Parkinsonian</b> (shuffling, festinating, ลดการแกว่งแขน), <b>cerebellar ataxic</b> (wide-based, เซ), <b>sensory ataxia</b> (stomping, Romberg +), antalgic</li><li><b>Neck stiffness</b>: นอนหงาย ผู้ตรวจรองใต้ศีรษะ งอคอไปที่คางแตะอก - ต้านหรือเจ็บ = positive (ระวังในผู้สงสัย cervical injury)</li><li><b>Kernig's sign</b>: งอสะโพกและเข่า 90 องศา แล้วค่อยๆ เหยียดเข่า - ต้านหรือเจ็บ (hamstring) ไม่สามารถเหยียดเต็มที่ = positive</li><li><b>Brudzinski's neck sign</b>: งอคอ -&gt; สะโพกและเข่างอเอง; Brudzinski's contralateral leg sign; jolt accentuation</li><li>ร่วมกับ fundoscopy (papilledema), photophobia, ผื่นจุดเลือดออก (meningococcemia)</li></ol>"},
  {id:"obabd", h:"Obstetric abdominal examination", tag:"ob", c:"<b>(a)</b> ประเมินอายุครรภ์ (fundal height), ท่าทารก (lie, presentation, position), engagement, และ FHS. <b>Fundal height</b>: ~12 สัปดาห์ เหนือ symphysis; ~16 สัปดาห์ กึ่งกลาง symphysis-สะดือ; ~20 สัปดาห์ ที่ระดับสะดือ; ~36 สัปดาห์ ที่ xiphoid. หลัง 24-28 สัปดาห์ ความสูงยอดมดลูกเป็น cm ≈ GA (สัปดาห์) ±2 cm. FHR ปกติ 110-160 bpm.<br><b>(b) ขั้นตอน</b><ol><li>ผู้ป่วยปัสสาวะก่อน นอนหงาย งอเข่า เล็กน้อย (ศีรษะหนุนหมอน) เปิดท้อง; ผู้ตรวจนั่ง/ยืนด้านขวา; มืออุ่น; ตรวจ BP, น้ำหนัก, บวม ก่อน</li><li><b>Inspection</b>: รูปร่างมดลูก (ตามยาว/ขวาง), ขนาด, striae gravidarum, linea nigra, scars (C-section), การดิ้นของทารก, สะดือ</li><li><b>วัดความสูงยอดมดลูก</b>: สายวัดจากขอบบน symphysis pubis ถึงยอดมดลูก (fundus) ด้านที่นูนที่สุด; บันทึก cm; ใช้ ultrasound ตามข้อบ่งชี้</li><li><b>Leopold's maneuver 1 (fundal grip)</b>: ผู้ตรวจหันหน้าไปทางศีรษะผู้ป่วย; 2 มือประคอง fundus - ระดับยอดมดลูก และส่วนทารกที่ fundus (ก้น = นุ่ม/กว้าง/ไม่กลม; ศีรษะ = แข็ง กลม ballotable)</li><li><b>Leopold 2 (umbilical / lateral grip)</b>: มือ 2 ข้างวางสองด้านของท้อง กดสลับ - หลังเด็ก = เรียบ แข็ง ต่อเนื่อง; แขนขา = ก้อนเล็ก ขยับ -&gt; บอก fetal lie / back position</li><li><b>Leopold 3 (first pelvic / Pawlik's grip)</b>: มือขวาเหนือ symphysis จับด้วยนิ้วหัวแม่มือ-นิ้วอื่น - ส่วนนำ (ศีรษะ/ก้น/ท่าขวาง), ลอย (floating) หรือ engaged</li><li><b>Leopold 4 (second pelvic grip)</b>: ผู้ตรวจ <b>หันหน้าไปทางเท้า</b> ผู้ป่วย; นิ้วทั้งสองมือชี้ลงช่องเชิงกราน คลำ cephalic prominence และระดับการเข้าสู่ pelvis (engagement - นับเป็น fifths palpable เหนือ brim)</li><li><b>FHS</b>: Doppler (ตั้งแต่ ~10-12 สัปดาห์) หรือ Pinard stethoscope (~20 สัปดาห์) ฟังที่ด้านหลังเด็ก/anterior shoulder; นับ 1 นาที (ปกติ 110-160 bpm); คลำ maternal pulse เทียบ; ประเมินรูปแบบการหดรัดตัวของมดลูก</li></ol>"},
  {id:"pelvic", h:"Pelvic examination (speculum, bimanual, Pap)", tag:"ob", c:"<b>(a)</b> ตรวจ external genitalia, vagina, cervix ด้วย speculum, bimanual (cervix, uterus, adnexa). ปากมดลูกปกติ: ชมพู เรียบ os กลม (nulliparous) หรือ slit/fish-mouth (parous). ในครรภ์: Chadwick's sign (ม่วงคล้ำ), Goodell's sign (ปากมดลูกนุ่ม), Hegar's sign. มดลูก ปกติ anteverted, anteflexed, ขนาดประมาณ 7x5x3 cm; รังไข่ ~3x2x1 cm.<br><b>(b) ขั้นตอน</b><ol><li>อธิบาย ขอ consent, มี <b>chaperone</b>, ปัสสาวะก่อน; ท่า <b>lithotomy</b> คลุมผ้า; แสงสว่างพอ; ถุงมือ</li><li><b>External</b>: ดู pubic hair, labia majora/minora, clitoris, urethral meatus, Bartholin's/Skene's gland (กดเจ็บ), perineum, ผิว (แผล, หูด, ตกขาว); ให้เบ่งดู cystocele / rectocele / prolapse</li><li><b>Speculum</b>: เลือกขนาด (Pederson/Graves); อุ่นและหล่อลื่นด้วยน้ำ (ถ้า Pap ใช้น้ำเท่านั้น); แยกริมฝีปาก สอดเฉียงเบาๆ ปิด blade แนวนอนหมุนเมื่อลึกสุด; เปิด blade ให้เห็นปากมดลูก; ล็อกสกรู; ดู cervix (สี, ectropion, polyp, Nabothian cyst, เลือด, ตกขาว) และผนังช่องคลอด</li><li><b>Pap smear</b>: ตรวจก่อนทา gel; (1) <b>ectocervix</b>: spatula (Ayre) วาง os หมุน 360 องศา; (2) <b>endocervix</b>: cytobrush สอดใน os หมุน ¼-½ รอบ; ป้ายบนสไลด์ทันที ไม่ทับกัน และ <b>fix</b> ด้วย 95% alcohol ทันที (หรือใช้ liquid-based cytology) ติดชื่อ; อาจเก็บ HPV test, wet mount (saline: clue cells, trichomonas; 10% KOH: whiff test, pseudohyphae), GC/CT</li><li>ปิดสกรู ปิด blade ช้าๆ ดึงออก หมุนดูผนังช่องคลอดขณะถอน</li><li><b>Bimanual</b>: สอด index+middle finger มือที่ถนัดที่หล่อลื่นแล้ว (คว่ำมือขึ้น); ตรวจ cervix (ตำแหน่ง, ความแข็ง, เคลื่อนไหว, <b>cervical motion tenderness</b> = PID/ectopic); มืออีกข้างกดหน้าท้องเหนือ symphysis: มดลูก (ขนาด รูปร่าง ตำแหน่ง ความแข็ง เคลื่อนไหว เจ็บ); adnexa ทั้งสองข้าง (ก้อน, เจ็บ) - รังไข่ปกติคลำได้ยาก; ถ้าคลำได้ในหญิงวัยหมดประจำเดือนถือว่าผิดปกติ</li><li>ถ้าจำเป็น <b>rectovaginal exam</b> (uterosacral ligaments, cul-de-sac); เช็ดทำความสะอาดผู้ป่วย; บันทึกผล และนัดผล Pap</li></ol>"},
  {id:"pedgrow", h:"Pediatric general and growth examination", tag:"ped", c:"<b>(a)</b> เด็กไม่ใช่ผู้ใหญ่ตัวเล็ก - ดูสภาพทั่วไป (กิจกรรม ร้องไห้ เล่น ปฏิสัมพันธ์), hydration, nutritional status, การเจริญเติบโต (growth chart), vital signs ตามอายุ, dysmorphic features, fontanelle.<br>เกณฑ์โดยประมาณ: HR ทารก 100-160, เด็กเล็ก 90-150, เด็กโต 60-100 /min; RR ทารกแรกเกิด 30-60, ทารก 30-50, toddler 24-40, school-age 18-30 /min; น้ำหนักแรกเกิด ~3 kg, 2 เท่าที่ ~4-5 เดือน, 3 เท่าที่ 1 ปี; ความยาวแรกเกิด ~50 cm, 1 ปี ~75 cm; รอบศีรษะแรกเกิด ~35 cm, 1 ปี ~46-47 cm, 2 ปี ~48-49 cm; anterior fontanelle ปิดเฉลี่ย ~12-18 เดือน, posterior ปิด 2-3 เดือน.<br><b>(b) ขั้นตอน</b><ol><li>สังเกตตั้งแต่เข้าห้อง (observation first): สีหน้า การหายใจ กิจกรรม ตามด้วยทำให้เด็กสบายใจ ใช้ของเล่น ให้พ่อแม่อุ้ม</li><li>ตรวจ <b>ตอนที่เด็กนิ่งก่อน</b> (ฟังหัวใจ-ปอด, นับ RR, คลำท้อง) แล้วค่อยตรวจที่ไม่ชอบ (หู คอ ปาก) เป็นลำดับสุดท้าย</li><li><b>Weight</b>: ชั่งเด็กไม่สวมเสื้อผ้า (เครื่องชั่งทารก &lt;2 ปี); <b>Length</b> (นอนหงาย, &lt;2 ปี) หรือ <b>Height</b> (ยืน, ≥2 ปี); <b>Head circumference</b>: สายวัดรอบเหนือคิ้ว (supraorbital ridge) ถึง occipital prominence ให้ได้เส้นรอบใหญ่สุด วัด 3 ครั้งใช้ค่าสูงสุด</li><li><b>Plot</b> น้ำหนัก-ส่วนสูง-รอบศีรษะลง growth chart (เกณฑ์ของไทย/WHO): weight-for-age, length/height-for-age, weight-for-length/height, BMI-for-age; เส้น percentile/SD</li><li><b>Hydration</b>: fontanelle บุ๋ม, mucous membrane แห้ง, ตาโหล, skin turgor, capillary refill, น้ำตา, ปัสสาวะ</li><li><b>Dysmorphic features</b>: รูปหน้า (Down: ตายาวเฉียงขึ้น, epicanthal fold, สันจมูกแบน, Brushfield spots, ลิ้นโตออก, เส้นเดียวฝ่ามือ), ใบหูต่ำ, ปากแหว่ง/เพดานโหว่, คอสั้น/web neck, hypertelorism; ผิว: café-au-lait, Mongolian spot (พบบ่อยในเด็กไทย, ปกติ), hemangioma, ผื่น</li><li><b>Fontanelle</b>: คลำ anterior fontanelle (ขนาด, ตึง/บุ๋ม/โป่ง - โป่งในร้องไห้ปกติ); posterior fontanelle; sutures; ดูรูปร่างศีรษะ</li><li>ตรวจ systematic ตามปกติ ปรับตามอายุ; BP ใช้ cuff กว้าง ~2/3 ของต้นแขน; Tanner stage ในวัยรุ่น</li></ol>"},
  {id:"newborn", h:"Newborn examination (APGAR, reflexes, hips)", tag:"ped", c:"<b>(a) APGAR score</b> ที่ 1 และ 5 นาที: <b>A</b>ppearance (สีผิว: 0 ซีด/เขียวทั้งตัว, 1 ตัวชมพูแต่ปลายเขียว, 2 ชมพูทั้งตัว), <b>P</b>ulse (0 ไม่มี, 1 &lt;100, 2 ≥100), <b>G</b>rimace (0 ไม่ตอบสนอง, 1 หน้าบูด, 2 ร้อง/ไอ), <b>A</b>ctivity (0 อ่อนปวกเปียก, 1 งอแขนขาเล็กน้อย, 2 ขยับดี), <b>R</b>espiration (0 ไม่หายใจ, 1 อ่อน/ไม่สม่ำเสมอ, 2 ร้องดี); รวม 0-10: 7-10 ปกติ, 4-6 moderate depression, 0-3 severe.<br>ปกติ: HR 120-160, RR 40-60, BT 36.5-37.5 C; น้ำหนัก 2,500-4,000 g (AGA); ประเมินอายุครรภ์ด้วย Ballard/New Ballard Score.<br><b>Primitive reflexes</b>: Moro (หายไป 4-6 เดือน), rooting (~3-4 เดือน), sucking, palmar grasp (หายไป ~4-6 เดือน), plantar grasp (9-12 เดือน), stepping/placing (~2 เดือน), ATNR/fencing (หายไป ~6 เดือน), Galant.<br><b>(b) ขั้นตอน</b><ol><li>ตรวจในห้องอุ่น เด็กนอนบนที่นอนเรียบ ถอดเสื้อผ้า; ดูภาพรวม: สี (เหลือง, เขียว), กิจกรรม, ร้อง, ท่านอน (flexed), ผิว (vernix, lanugo, Mongolian spots, erythema toxicum, milia)</li><li><b>หัว</b>: caput succedaneum, cephalhematoma, anterior/posterior fontanelle, sutures, รอบศีรษะ; <b>หน้า-ตา</b>: red reflex (ตรวจ cataract/retinoblastoma), เพดานปาก (cleft); หูตำแหน่ง; <b>คอ-clavicle</b>: คลำหัก (clavicular fracture), torticollis; Erb's palsy</li><li><b>หัวใจ-ปอด</b>: ฟัง murmur, <b>femoral pulses</b> (coarctation), RR; <b>ท้อง</b>: คลำตับ-ม้ามไต, สะดือ (2 arteries + 1 vein), hernia; <b>anus</b> เปิดหรือไม่ (imperforate anus), เคลื่อนถ่ายขี้เทา; <b>genitalia</b>: testes ลงถุง, hypospadias, ลักษณะเพศคลุมเครือ</li><li><b>Hips - Barlow and Ortolani</b> (DDH): ทารกนอนหงายบนพื้นเรียบ สะโพก-เข่างอ 90 องศา ตรวจทีละข้าง (มือหนึ่งจับ pelvis ให้นิ่ง); <b>Ortolani</b> = กาง (abduct) พร้อมยกที่ greater trochanter ไปข้างหน้า - รู้สึก 'clunk' เมื่อสะโพกที่หลุดเข้าที่ (reduction); <b>Barlow</b> = หุบ (adduct) พร้อมกดไปด้านหลัง - สะโพกหลุดออกได้ (dislocatable); ดู asymmetry of thigh folds, Galeazzi sign, limited abduction (&gt;3 เดือน)</li><li><b>Spine</b>: คว่ำทารก ดูกระดูกสันหลัง sacral dimple/tuft of hair; <b>Reflexes</b>: Moro (ตกประคอง), rooting, sucking, grasp, stepping; tone</li><li>ตรวจน้ำหนัก/ความยาว/รอบศีรษะ และคัดกรอง: <b>newborn screening</b> (TSH ฯลฯ), CCHD (pulse oximetry), hearing (OAE/AABR), jaundice (bilirubin), วัคซีน BCG/HBV, vitamin K</li></ol>"}
 ]
};
